import sys, heapq
from collections import defaultdict

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    q = defaultdict(list)
    for i in range(n):
        q[int(data[1 + i])].append(i)
    cnt = {a: len(v) for a, v in q.items()}
    if max(cnt.values()) > (n + 1) // 2:
        print(-1)
        return
    pos = {a: 0 for a in q}
    front = [(v[0], a) for a, v in q.items()]
    heapq.heapify(front)
    big = [(-c, a) for a, c in cnt.items()]
    heapq.heapify(big)
    last = None
    res = []
    for m in range(n, 0, -1):
        while -big[0][0] != cnt[big[0][1]]:
            heapq.heappop(big)
        if -big[0][0] > m // 2:
            b = big[0][1]
        else:
            while True:
                idx, a = front[0]
                if pos[a] < len(q[a]) and q[a][pos[a]] == idx:
                    break
                heapq.heappop(front)
            top = heapq.heappop(front)
            if top[1] == last:
                while True:
                    idx, a = front[0]
                    if pos[a] < len(q[a]) and q[a][pos[a]] == idx:
                        break
                    heapq.heappop(front)
                nxt = heapq.heappop(front)
                heapq.heappush(front, top)
                top = nxt
            b = top[1]
        res.append(q[b][pos[b]])
        pos[b] += 1
        cnt[b] -= 1
        last = b
        if cnt[b] > 0:
            heapq.heappush(front, (q[b][pos[b]], b))
            heapq.heappush(big, (-cnt[b], b))
    print(' '.join(map(str, res)))

